use crate::solver::enigma_settings::EnigmaRotorConfiguration;

use super::EnigmaSolver;

#[test]
fn test_known_plain_text_solver_1() {
    let plain_part = "";
    let cipher = "";

    let solver = EnigmaSolver::new(cipher, plain_part);
    let settings = solver.known_plain_text_cipher_break().unwrap();

    assert_eq!(settings.reflector.name, "Reflector A");

    assert_eq!(
        settings.rotor_config,
        EnigmaRotorConfiguration::new(1, 0, 3, 6, 8, 8)
    );
}
